#!/usr/bin/env python3
"""
CSV Summary Statistics Script

Reads a CSV file and prints summary statistics including:
- Number of rows and columns
- Column names
- Min, max, and mean for numeric columns
"""

import csv
import sys
import os


def is_numeric(value):
    """Check if a string value can be converted to a number."""
    if not value or value.isspace():
        return False
    try:
        float(value)
        return True
    except ValueError:
        return False


def safe_float(value):
    """Safely convert a value to float, returning None if not possible."""
    try:
        return float(value)
    except (ValueError, TypeError):
        return None


def analyze_csv(file_path):
    """Analyze CSV file and return summary statistics."""
    try:
        with open(file_path, 'r', newline='', encoding='utf-8') as file:
            # Use Sniffer to detect dialect
            sample = file.read(1024)
            file.seek(0)

            try:
                dialect = csv.Sniffer().sniff(sample)
            except csv.Error:
                # Fall back to default dialect if sniffing fails
                dialect = csv.excel

            reader = csv.reader(file, dialect)

            # Read header
            try:
                headers = next(reader)
            except StopIteration:
                return {
                    'error': 'File is empty',
                    'rows': 0,
                    'columns': 0,
                    'column_names': [],
                    'numeric_stats': {}
                }

            # Initialize data structures
            num_columns = len(headers)
            column_data = {header: [] for header in headers}
            row_count = 0

            # Read data rows
            for row in reader:
                row_count += 1
                # Pad row if it has fewer columns than headers
                while len(row) < num_columns:
                    row.append('')

                # Store data for each column (only up to header count)
                for i, header in enumerate(headers):
                    if i < len(row):
                        column_data[header].append(row[i])
                    else:
                        column_data[header].append('')

            # Analyze numeric columns
            numeric_stats = {}
            for header, values in column_data.items():
                # Check if column is predominantly numeric
                non_empty_values = [v for v in values if v and not v.isspace()]
                if not non_empty_values:
                    continue

                numeric_values = [safe_float(v) for v in non_empty_values if is_numeric(v)]

                # Consider column numeric if at least 80% of non-empty values are numeric
                if len(numeric_values) >= 0.8 * len(non_empty_values) and len(numeric_values) > 0:
                    numeric_stats[header] = {
                        'min': min(numeric_values),
                        'max': max(numeric_values),
                        'mean': sum(numeric_values) / len(numeric_values),
                        'count': len(numeric_values),
                        'total_values': len(non_empty_values)
                    }

            return {
                'rows': row_count,
                'columns': num_columns,
                'column_names': headers,
                'numeric_stats': numeric_stats
            }

    except FileNotFoundError:
        return {'error': f'File not found: {file_path}'}
    except PermissionError:
        return {'error': f'Permission denied: {file_path}'}
    except UnicodeDecodeError:
        return {'error': f'Unable to decode file (encoding issue): {file_path}'}
    except csv.Error as e:
        return {'error': f'CSV parsing error: {e}'}
    except Exception as e:
        return {'error': f'Unexpected error: {e}'}


def print_summary(stats):
    """Print formatted summary statistics."""
    if 'error' in stats:
        print(f"Error: {stats['error']}", file=sys.stderr)
        return

    print("CSV File Summary")
    print("=" * 50)
    print(f"Number of rows: {stats['rows']}")
    print(f"Number of columns: {stats['columns']}")

    print(f"\nColumn names:")
    for i, name in enumerate(stats['column_names'], 1):
        print(f"  {i}. {name}")

    if stats['numeric_stats']:
        print(f"\nNumeric column statistics:")
        print("-" * 30)
        for col_name, col_stats in stats['numeric_stats'].items():
            print(f"\n{col_name}:")
            print(f"  Min:  {col_stats['min']:,.6g}")
