```python
#!/usr/bin/env python3
"""
CSV Summary Statistics Script

Reads a CSV file and displays summary statistics including:
- Number of rows and columns
- Column names
- Min, max, and mean for numeric columns
"""

import csv
import sys
import os


def is_numeric(value):
    """Check if a string value represents a number (int or float)."""
    if not value or value.isspace():
        return False
    try:
        float(value)
        return True
    except ValueError:
        return False


def safe_float(value):
    """Convert string to float, return None if conversion fails."""
    try:
        return float(value)
    except (ValueError, TypeError):
        return None


def analyze_csv(filepath):
    """Analyze CSV file and return summary statistics."""
    try:
        with open(filepath, 'r', newline='', encoding='utf-8') as file:
            # Use Sniffer to detect dialect, fallback to excel if detection fails
            try:
                sample = file.read(1024)
                file.seek(0)
                dialect = csv.Sniffer().sniff(sample)
                reader = csv.reader(file, dialect)
            except csv.Error:
                file.seek(0)
                reader = csv.reader(file)

            # Read header
            try:
                headers = next(reader)
            except StopIteration:
                return {"error": "File is empty"}

            num_columns = len(headers)
            num_rows = 0

            # Initialize data structures for numeric analysis
            column_data = {i: [] for i in range(num_columns)}
            column_is_numeric = {i: True for i in range(num_columns)}

            # Process data rows
            for row_num, row in enumerate(reader, start=2):  # Start at 2 (header is row 1)
                num_rows += 1

                # Handle rows with different column counts
                while len(row) < num_columns:
                    row.append('')

                # Analyze each column value
                for col_idx in range(min(num_columns, len(row))):
                    value = row[col_idx].strip()

                    if column_is_numeric[col_idx]:
                        if value == '':
                            # Empty values are ignored for numeric analysis
                            continue
                        elif is_numeric(value):
                            column_data[col_idx].append(safe_float(value))
                        else:
                            # Column contains non-numeric data
                            column_is_numeric[col_idx] = False
                            column_data[col_idx] = []

            # Calculate statistics for numeric columns
            numeric_stats = {}
            for col_idx, is_numeric_col in column_is_numeric.items():
                if is_numeric_col and column_data[col_idx]:
                    values = column_data[col_idx]
                    numeric_stats[headers[col_idx]] = {
                        'min': min(values),
                        'max': max(values),
                        'mean': sum(values) / len(values),
                        'count': len(values)
                    }

            return {
                'num_rows': num_rows,
                'num_columns': num_columns,
                'headers': headers,
                'numeric_stats': numeric_stats
            }

    except FileNotFoundError:
        return {"error": f"File not found: {filepath}"}
    except PermissionError:
        return {"error": f"Permission denied: {filepath}"}
    except UnicodeDecodeError:
        return {"error": f"Unable to decode file. File may be binary or use unsupported encoding: {filepath}"}
    except Exception as e:
        return {"error": f"Error reading file: {e}"}


def print_results(results):
    """Print the analysis results in a formatted way."""
    if "error" in results:
        print(f"Error: {results['error']}", file=sys.stderr)
        return

    print("CSV FILE SUMMARY")
    print("=" * 50)
    print(f"Number of rows: {results['num_rows']:,}")
    print(f"Number of columns: {results['num_columns']}")

    print(f"\nColumn names:")
    for i, header in enumerate(results['headers'], 1):
        print(f"  {i:2d}. {header}")

    if results['numeric_stats']:
        print(f"\nNumeric column statistics:")
        print(f"{'Column':<20} {'Min':<12} {'Max':<12} {'Mean':<12} {'Count':<8}")
        print("-" * 68)

        for col_name, stats in results['numeric_stats'].items():
            # Format numbers appropriately
            min_val = f"{stats['min']:,.3f}".rstrip('0').rstrip('.')
            max_val = f"{stats['max']:,.3f}".rstrip('0').rstrip('.')
            mean_val = f"{stats['mean']:,.3f}".rstrip('0').rstrip('.')

            print(f"{col_name:<20} {min_val:<12} {max_val:<12} {mean_val:<12} {stats['count']:<8}")
    else:
        print(f"\nNo numeric columns found.")


def main():
    """Main function to handle command line arguments and orchestrate analysis."""
    if len(sys.argv) != 2:
        print("Usage: python csv_summary.py <csv_file_path>", file=sys.stderr)
        print("", file=sys.stderr)
        print("Example: python csv_summary.py data.csv", file=sys.stderr)
        sys.exit(1)

    csv_file = sys.argv[1]

    # Basic file validation
    if not os.path.exists(csv_file):
        print(f"Error: File '{csv_file}' does not exist.", file=sys.stderr)
        sys.exit(1)

    if not os.path.isfile(csv_file):
        print(f"Error: '{csv_file}' is not a file.", file=sys.stderr)
        sys.exit(1)

    # Analyze the CSV file
    results = analyze_csv(csv_file)

    # Print results
    print_results(results)

    # Exit with appropriate code
    if "error" in results:
        sys.exit(1)


if __name__ == "__main__":
    main()
```

