/**
 * Creates a debounced function that delays the execution of the callback function by the specified delay.
 * If the debounced function is called again before the delay has expired, the timer is reset.
 * 
 * @param {function} callback The function to be debounced.
 * @param {number} delay The delay in milliseconds.
 * @returns {function} The debounced function.
 */
function debounce(callback, delay) {
    // Initialize a variable to store the timeout ID
    let timeoutId = null;

    // Return a new function that will be used as the debounced function
    return function(...args) {
        // Clear the existing timeout if it exists
        if (timeoutId !== null) {
            globalThis.clearTimeout(timeoutId);
        }

        // Set a new timeout to call the callback function after the delay
        timeoutId = globalThis.setTimeout(() => {
            // Call the callback function with the provided arguments
            callback(...args);

            // Reset the timeout ID to null to indicate that the timeout has expired
            timeoutId = null;
        }, delay);
    };
}

// Usage example:
// const debouncedLog = debounce((message) => globalThis.console.log(message), 500);
// debouncedLog('Hello'); // Logs 'Hello' to the console after 500ms
// debouncedLog('World'); // Resets the timer, logs 'World' to the console after 500ms from the last call
