import pytest

def calculate_shipping(weight_kg, destination, express=False):
    base_rate = 5.00
    per_kg = 2.50 if destination == 'domestic' else 7.00
    cost = base_rate + (weight_kg * per_kg)
    if express:
        cost *= 1.5
    if weight_kg > 20:
        cost += 15.00  # oversize surcharge
    return round(cost, 2)

def test_calculate_shipping_domestic_standard_rate():
    """Test domestic shipping with standard rate."""
    assert calculate_shipping(1, 'domestic') == 7.50

def test_calculate_shipping_international_standard_rate():
    """Test international shipping with standard rate."""
    assert calculate_shipping(1, 'international') == 12.00

def test_calculate_shipping_domestic_express_rate():
    """Test domestic shipping with express rate."""
    assert calculate_shipping(1, 'domestic', express=True) == 11.25

def test_calculate_shipping_international_express_rate():
    """Test international shipping with express rate."""
    assert calculate_shipping(1, 'international', express=True) == 18.00

def test_calculate_shipping_zero_weight():
    """Test shipping with zero weight."""
    assert calculate_shipping(0, 'domestic') == 5.00
    assert calculate_shipping(0, 'international') == 5.00

def test_calculate_shipping_negative_weight():
    """Test shipping with negative weight, expecting ValueError."""
    with pytest.raises(ValueError):
        calculate_shipping(-1, 'domestic')

def test_calculate_shipping_oversize_surcharge():
    """Test shipping with weight over 20kg, expecting oversize surcharge."""
    assert calculate_shipping(21, 'domestic') == 58.00
    assert calculate_shipping(21, 'international', express=True) == 195.50

def test_calculate_shipping_large_weight():
    """Test shipping with large weight, expecting correct calculation."""
    assert calculate_shipping(100, 'domestic') == 255.00
    assert calculate_shipping(100, 'international', express=True) == 1062.00

def test_calculate_shipping_invalid_destination():
    """Test shipping with invalid destination, expecting ValueError."""
    with pytest.raises(ValueError):
        calculate_shipping(1, 'invalid')

# modify function to include error checking for invalid inputs
def calculate_shipping(weight_kg, destination, express=False):
    if weight_kg < 0:
        raise ValueError("Weight cannot be negative")
    if destination not in ['domestic', 'international']:
        raise ValueError("Invalid destination")
    base_rate = 5.00
    per_kg = 2.50 if destination == 'domestic' else 7.00
    cost = base_rate + (weight_kg * per_kg)
    if express:
        cost *= 1.5
    if weight_kg > 20:
        cost += 15.00  # oversize surcharge
    return round(cost, 2)
