/**
 * Creates a debounced function that delays invoking the provided callback until
 * after the specified wait time has elapsed since the last time the debounced
 * function was invoked.
 * 
 * @param {Function} callback - The function to debounce
 * @param {number} delay - The number of milliseconds to delay
 * @returns {Function} A new debounced function
 * 
 * @example
 * // Example: Search as you type with debounce
 * const searchInput = document.getElementById('search');
 * const debouncedSearch = debounce((query) => {
 *   console.log('Searching for:', query);
 *   // Perform actual search operation here
 * }, 300);
 * 
 * searchInput.addEventListener('input', (e) => {
 *   debouncedSearch(e.target.value);
 * });
 * 
 * // In this example, the search function will only execute 300ms 
 * // after the user stops typing
 */
function debounce(callback, delay) {
  let timeoutId;

  return function(...args) {
    // Clear the previous timeout if it exists
    if (timeoutId) {
      clearTimeout(timeoutId);
    }

    // Set a new timeout to execute the callback after the delay
    timeoutId = setTimeout(() => {
      callback.apply(this, args);
      timeoutId = null;
    }, delay);
  };
}
