import csv
import sys
from typing import List, Dict, Union, Optional

def main() -> None:
    # Check if a file path was provided
    if len(sys.argv) != 2:
        print("Usage: python script.py <path_to_csv_file>")
        sys.exit(1)

    file_path = sys.argv[1]

    # Try to open and read the CSV file
    try:
        with open(file_path, 'r', newline='', encoding='utf-8') as file:
            reader = csv.reader(file)

            # Read the header (first row)
            try:
                header = next(reader)
            except StopIteration:
                print(f"Error: The file '{file_path}' is empty.")
                sys.exit(1)

            # Initialize variables for tracking data
            rows = list(reader)  # Read all remaining rows
            num_rows = len(rows)
            num_cols = len(header)

            # Print basic info
            print(f"Number of rows: {num_rows}")
            print(f"Number of columns: {num_cols}")
            print(f"Column names: {', '.join(header)}")

            # Initialize statistics for numeric columns
            numeric_cols = {}
            for i, col_name in enumerate(header):
                numeric_cols[col_name] = {
                    'values': [],
                    'index': i
                }

            # Extract values for each column and try to convert to float
            for row_num, row in enumerate(rows, start=2):  # start=2 because header is row 1
                if len(row) != num_cols:
                    print(f"Warning: Row {row_num} has {len(row)} columns, expected {num_cols}. Skipping row.")
                    continue

                for i, (col_name, value) in enumerate(zip(header, row)):
                    value = value.strip()
                    if value == '':
                        continue  # Skip empty values

                    try:
                        numeric_value = float(value)
                        numeric_cols[col_name]['values'].append(numeric_value)
                    except ValueError:
                        # Not a numeric value, remove this column from numeric_cols if it's there
                        if col_name in numeric_cols and numeric_cols[col_name]['values']:
                            # Keep it only if we've already seen numeric values
                            continue
                        else:
                            # Remove entirely if no numeric values found yet
                            if col_name in numeric_cols:
                                del numeric_cols[col_name]

            # Print statistics for numeric columns
            if numeric_cols:
                print("\nNumeric column statistics:")
                for col_name in header:
                    if col_name in numeric_cols and numeric_cols[col_name]['values']:
                        values = numeric_cols[col_name]['values']
                        col_min = min(values)
                        col_max = max(values)
                        col_mean = sum(values) / len(values)
                        print(f"  {col_name}: min={col_min}, max={col_max}, mean={col_mean:.6f}")
            else:
                print("\nNo numeric columns found.")

    except FileNotFoundError:
        print(f"Error: File '{file_path}' not found.")
        sys.exit(1)
    except PermissionError:
        print(f"Error: Permission denied when reading '{file_path}'.")
        sys.exit(1)
    except Exception as e:
        print(f"Error: An unexpected error occurred while reading the file: {e}")
        sys.exit(1)

if __name__ == "__main__":
    main()
