```javascript
/**
 * Creates a debounced version of the provided callback.
 * The callback is only invoked after the specified delay has elapsed
 * since the last time the returned function was called. Each new call
 * resets the timer.
 *
 * @param {Function} callback - The function to debounce.
 * @param {number} delay - Delay in milliseconds.
 * @returns {Function} A debounced function.
 *
 * @example
 * // Usage:
 * const log = debounce((msg) => console.log(msg), 200);
 * log('hello'); // timer starts, will fire after 200ms
 * log('world'); // resets timer, so only 'world' logs 200ms later
 */
function debounce(callback, delay) {
  let timerId;

  return function (...args) {
    clearTimeout(timerId);               // Cancel previous pending execution
    const context = this;                // Preserve `this` for the callback
    timerId = setTimeout(() => {
      callback.apply(context, args);     // Execute with correct context & args
    }, delay);
  };
}
