/**
 * Creates a debounced function that delays invoking `callback` until after `delay` milliseconds
 * have elapsed since the last time the debounced function was invoked.
 * The callback is called with the arguments and `this` context from the most recent invocation.
 *
 * @param {Function} callback - The function to debounce.
 * @param {number} delay - The number of milliseconds to wait before invoking `callback`.
 * @returns {Function} A new debounced version of the provided function.
 *
 * @example
 * // Create a debounced version of a logger
 * const log = debounce((msg) => console.log(msg), 300);
 * 
 * log('Hello'); // Nothing printed yet
 * log('World'); // Timer resets; 'World' will be printed once 300ms of inactivity pass
 * // After 300ms: 'World' appears in console
 */
function debounce(callback, delay) {
  let timerId;

  return function(...args) {
    clearTimeout(timerId);

    // Capture the current `this` context for the delayed call
    const context = this;

    timerId = setTimeout(() => {
      callback.apply(context, args);
    }, delay);
  };
}
