/**
 * Creates a debounced function that delays invoking `callback` until after `delay` milliseconds
 * have elapsed since the last time the debounced function was invoked.
 * The debounced function preserves the `this` context and all arguments passed to it.
 *
 * @param {Function} callback - The function to debounce.
 * @param {number} delay - The delay in milliseconds.
 * @returns {Function} - The debounced function, with an optional `.cancel()` method.
 *
 * @example
 * // Usage:
 * const log = debounce((msg) => console.log(msg), 300);
 * log('Hello');  // Does not log immediately
 * log('World');  // Cancels previous call, resets timer
 * // After 300ms of inactivity, logs only 'World'.
 */
function debounce(callback, delay) {
  let timeoutId;

  const debounced = function (...args) {
    const context = this; // preserve the calling context
    clearTimeout(timeoutId);
    timeoutId = setTimeout(() => {
      callback.apply(context, args);
    }, delay);
  };

  // Optional: allow manual cancellation of pending invocation
  debounced.cancel = function () {
    clearTimeout(timeoutId);
    timeoutId = null;
  };

  return debounced;
}
