import csv
import sys

def is_numeric_column(values):
    """Return True if all values in the list can be converted to float."""
    for v in values:
        # Skip empty strings (treat as non-numeric)
        if v.strip() == '':
            return False
        try:
            float(v.strip())
        except ValueError:
            return False
    return True

def main():
    if len(sys.argv) < 2:
        print("Usage: python script.py <csv_file>")
        sys.exit(1)

    filepath = sys.argv[1]

    try:
        with open(filepath, newline='') as f:
            reader = csv.reader(f)
            # Read all rows into memory (for small to moderate CSVs)
            rows = list(reader)
    except FileNotFoundError:
        print(f"Error: File '{filepath}' not found.")
        sys.exit(1)
    except Exception as e:
        print(f"Error reading file: {e}")
        sys.exit(1)

    if not rows:
        print("CSV file is empty.")
        sys.exit(0)

    # Assume first row is header
    header = rows[0]
    num_columns = len(header)
    data_rows = rows[1:]

    print(f"Number of rows: {len(data_rows)}")
    print(f"Number of columns: {num_columns}")
    print(f"Column names: {', '.join(header)}")

    # Transpose data: list of columns, each column a list of values (strings)
    columns = [[] for _ in range(num_columns)]
    for row in data_rows:
        # Pad row if shorter than header (in case of ragged CSV)
        for i in range(num_columns):
            if i < len(row):
                columns[i].append(row[i])
            else:
                columns[i].append('')  # treat missing as empty string

    print("\nNumeric columns:")
    any_numeric = False
    for idx, col_name in enumerate(header):
        values = columns[idx]
        if not values:
            continue
        if is_numeric_column(values):
            any_numeric = True
            # Convert to floats
            floats = [float(v.strip()) for v in values if v.strip() != '']
            if floats:
                min_val = min(floats)
                max_val = max(floats)
                mean_val = sum(floats) / len(floats)
                print(f"  - {col_name}: min={min_val}, max={max_val}, mean={mean_val:.4f}")
            else:
                print(f"  - {col_name}: (no valid numeric data)")

    if not any_numeric:
        print("  (none)")

if __name__ == "__main__":
    main()
